use anatomy::Anatomy;
use body::BodyCage;
use cage::{Cage, Subdivided, fit, subdivide_levels};
use genitals::Variant;

use crate::error::Result;

/// Catmull-Clark levels from the cage to the template surface.
pub const LEVELS: usize = 2;
/// Fixed-point iterations of the cage fit.
pub const FIT_ITERATIONS: usize = 12;

/// The body surface: the fitted cage and its subdivision levels (the last is the surface).
#[derive(Clone, Debug)]
pub struct Surface {
    /// The anatomy it was built from.
    pub anatomy: Anatomy,
    /// The fitted cage with its loops.
    pub body: BodyCage,
    /// The designed cage positions (before the fit).
    pub targets: Vec<humanart_math::Vec3>,
    /// The subdivision levels; the last one's cage is the surface.
    pub levels: Vec<Subdivided>,
    /// The genital variant inside the groin attachment loop (ADR-039).
    pub variant: Variant,
}

impl Surface {
    /// The final surface mesh.
    pub fn mesh(&self) -> &Cage {
        self.levels.last().map_or(&self.body.cage, |l| &l.cage)
    }
}

/// Builds the body surface `[MOD-01]` with the default genital variant.
pub fn body_surface() -> Result<Surface> {
    body_surface_with(Variant::default())
}

/// Builds the body surface `[MOD-01]` with the given genital variant (ADR-039).
pub fn body_surface_with(variant: Variant) -> Result<Surface> {
    body_surface_for(variant, anatomy::Auricle::Base)
}

/// Builds the body surface `[MOD-01]` with the given genital variant (ADR-039) and auricle design.
pub fn body_surface_for(variant: Variant, auricle: anatomy::Auricle) -> Result<Surface> {
    let anatomy = Anatomy { auricle, ..Anatomy::neutral() };
    let mut body = body::build_with(&anatomy, variant)?;
    let creases: std::collections::HashSet<(u32, u32)> =
        body.loops.creases.iter().map(|&(a, b)| (a.min(b), a.max(b))).collect();
    let sharp = |a: u32, b: u32| creases.contains(&(a.min(b), a.max(b)));
    let targets = body.cage.pos.clone();
    fit(&mut body.cage, &targets, LEVELS, FIT_ITERATIONS, &sharp);
    let mut levels = subdivide_levels(&body.cage, LEVELS, &sharp);
    if let Some(last) = levels.last_mut() {
        relief::fair_cheeks(&mut last.cage, &anatomy);
        relief::apply(&mut last.cage, &anatomy);
    }
    Ok(Surface { anatomy, body, targets, levels, variant })
}

